\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{booktabs}

\title{Bench Calibration of a Tipping-Bucket Rain Gauge}
\author{Field Hydrology Group}
\date{May 2026}

\begin{document}
\maketitle

\section{Objective}
The group's tipping-bucket rain gauge No.~4 has been in service
for nine years without a bench recalibration.
This note reports a laboratory recalibration against a
reference volumetric dispenser and derives the correction to
apply to the archive before the gauge is redeployed.

\section{Apparatus}
The gauge has a nominal resolution of 0.2~mm per tip.
The reference dispenser delivers known volumes between 50 and
500~ml through a nozzle plate that mimics natural drop sizes.
A data logger records tip timestamps to one-second resolution.
All tests ran at room temperature with the gauge levelled on a
vibration-damped bench.

\section{Procedure}
Three delivery rates were tested, corresponding roughly to
10, 40, and 90~mm/h.
At each rate, five runs of 500~ml were delivered and the number
of tips was counted.
The measured volume per tip follows directly from the delivered
volume, the funnel catchment area of 200~cm$^2$, and the tip
count.
Runs in which the logger dropped a timestamp were repeated.

\section{Field Notes}
The gauge was inspected after every storm event.\\
Daily totals were read at 08:00 local time and logged by hand
in the site notebook before the memory card was cleared, and
the funnel was brushed free of needles and grit at each visit.

\section{Results}
The measured volume per tip drifts upward with delivery rate,
from 0.196~mm at the slow rate to 0.211~mm at the fast rate;
the per-rate results are listed in Table~\ref{tab:calib}.
The drift is consistent with water retained on the bucket
surface at high inflow, and a single linear correction in rate
recovers the delivered volume to within 1.5\% at all three
rates.

\begin{table}[h]
\centering
\begin{tabular}{lcc}
\toprule
Nominal rate (mm/h) & Tips per 500~ml & Volume per tip (mm) \\
\midrule
10 & 128 & 0.196 \\
40 & 124 & 0.202 \\
90 & 119 & 0.211 \\
\bottomrule
\end{tabular}
\caption{Measured volume per tip at three delivery rates}
\label{tab:calib-results}
\end{table}

\section{Conclusions}
The gauge underreads at high intensity by up to 5\% relative to
its nominal resolution, and the underread grows smoothly with
delivery rate.
A rate-dependent correction should be applied to the nine-year
archive before the gauge is redeployed, and the bench test
should be repeated every three years.

\end{document}
